function mean(xs){return xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;}
export function travelPilotMetrics(sessions=[]){const valid=sessions.filter(x=>Number.isFinite(x.decisionSeconds));return{sampleCount:valid.length,meanDecisionSeconds:mean(valid.map(x=>x.decisionSeconds)),newPlaceDiscoveryRate:valid.length?valid.filter(x=>x.discoveredNewPlace===true).length/valid.length:null,whyNowOpenedRate:valid.length?valid.filter(x=>x.whyNowOpened===true).length/valid.length:null};}
export function environmentLearningMetrics(rows=[]){const pairs=rows.filter(x=>Number.isFinite(x.preScore)&&Number.isFinite(x.postScore));return{sampleCount:pairs.length,meanPre:mean(pairs.map(x=>x.preScore)),meanPost:mean(pairs.map(x=>x.postScore)),meanGain:mean(pairs.map(x=>x.postScore-x.preScore))};}
export function traceabilityMetrics(rows=[]){const valid=rows.filter(x=>x.outputShown===true);return{sampleCount:valid.length,sourceVisibleRate:valid.length?valid.filter(x=>x.sourceVisible===true).length/valid.length:null,truthLabelVisibleRate:valid.length?valid.filter(x=>x.truthLabelVisible===true).length/valid.length:null};}
